from subprocess import run, CalledProcessError

@dataclass(frozen=True)
class CommandResult:
    returncode: int
    stdout: str
    stderr: str


def run_python(python_executable: str, arguments: list[str]) -> CommandResult:
    allowed = (['--version'],)
    if tuple(arguments) != allowed[0]:
        raise ValueError("only --version is allowed")
    try:
        result = run(
            [python_executable, *arguments],
            capture_output=True,
            text=True,
            check=False,
        )
    except OSError as exc:
        raise RuntimeError("could not start interpreter") from exc
    return CommandResult(result.returncode, result.stdout, result.stderr)

