from __future__ import annotations

from dataclasses import dataclass


class InventoryError(ValueError):
    """Raised when an inventory operation violates a business rule."""


@dataclass(frozen=True, slots=True)
class InventoryKey:
    sku: str

    def __post_init__(self) -> None:
        normalized = self.sku.strip().upper()
        if not normalized or len(normalized) > 32:
            raise InventoryError("SKU must contain 1 to 32 non-whitespace characters")
        object.__setattr__(self, "sku", normalized)


@dataclass(slots=True)
class InventoryItem:
    key: InventoryKey
    name: str
    quantity: int

    def __post_init__(self) -> None:
        self.name = self.name.strip()
        if not self.name:
            raise InventoryError("item name is required")
        if self.quantity < 0:
            raise InventoryError("quantity cannot be negative")

    def adjust(self, delta: int) -> None:
        new_quantity = self.quantity + delta
        if new_quantity < 0:
            raise InventoryError("quantity cannot become negative")
        self.quantity = new_quantity

from __future__ import annotations

import logging

from .domain import InventoryError, InventoryItem, InventoryKey
from .repository import InventoryRepository

logger = logging.getLogger(__name__)


class InventoryService:
    def __init__(self, repository: InventoryRepository) -> None:
        self.repository = repository

    def add(self, sku: str, name: str, quantity: int) -> InventoryItem:
        key = InventoryKey(sku)
        if self.repository.get(key) is not None:
            raise InventoryError("SKU already exists")
        item = InventoryItem(key, name, quantity)
        saved = self.repository.add_or_update(item, "add", quantity)
        logger.info("inventory item added", extra={"sku": key.sku})
        return saved

    def adjust(self, sku: str, delta: int) -> InventoryItem:
        key = InventoryKey(sku)
        item = self.repository.get(key)
        if item is None:
            raise InventoryError("SKU not found")
        item.adjust(delta)
        saved = self.repository.add_or_update(item, "adjust", delta)
        logger.info("inventory adjusted", extra={"sku": key.sku})
        return saved

    def list_items(self) -> list[InventoryItem]:
        return list(self.repository.list_items())

    def history(self, sku: str):
        return self.repository.history(InventoryKey(sku))

