        item = InventoryItem(InventoryKey("A"), "Widget", 3)
        with self.assertRaises(InventoryError):
            item.adjust(-4)

    def test_adjust_accepts_positive_and_negative_deltas_that_remain_valid(self):
        item = InventoryItem(InventoryKey("A"), "Widget", 3)
        item.adjust(4)
        self.assertEqual(item.quantity, 7)
        item.adjust(-2)
        self.assertEqual(item.quantity, 5)

